-- Aggregate-only inventory. Run inside a read-only transaction with bounded timeouts.
SELECT now() db_time,current_setting('transaction_read_only') read_only;
SELECT choice,state,count(*) profiles,count(*) FILTER(WHERE expires_at>now()) unexpired,count(*) FILTER(WHERE created_at>=now()-interval '7 days') created_last_7d FROM recommendation_profile GROUP BY 1,2;
SELECT scope,state,count(*) generations,count(*) FILTER(WHERE expires_at>now()) unexpired,percentile_cont(0.5) within group(order by contribution_count) median_contributions,max(contribution_count) max_contributions FROM recommendation_profile_projection_generation GROUP BY 1,2;
SELECT scope,state,failure_reason,count(*) runs,min(created_at) oldest_created,max(created_at) latest_created FROM recommendation_profile_projection_run GROUP BY 1,2,3 ORDER BY runs DESC;
SELECT g.manifest_id,g.scope,g.state,count(*) current_pointers,count(*) FILTER(WHERE g.expires_at>now()) unexpired,count(*) FILTER(WHERE g.contribution_count=0) empty,count(*) FILTER(WHERE g.durable_interest_count>0) with_durable_interests,count(*) FILTER(WHERE g.session_intent_present) with_session_intent,min(g.published_at) oldest_published,max(g.published_at) newest_published FROM recommendation_profile_projection_pointer ptr JOIN recommendation_profile_projection_generation g ON g.id=ptr.generation_id GROUP BY 1,2,3;
SELECT kind,count(*) interests,count(*) FILTER(WHERE expires_at>now()) unexpired FROM recommendation_profile_interest GROUP BY 1;
SELECT relname,n_live_tup FROM pg_stat_user_tables WHERE relname IN ('recommendation_profile','recommendation_profile_projection_generation','recommendation_profile_projection_contribution','recommendation_profile_projection_pointer','recommendation_profile_interest','recommendation_profile_projection_run','recommendation_candidate_stage_evidence');
